<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientTenantVO;
use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;

final class TrustedClientTenantVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new TenantRef('one');
        $ref = TrustedClientTenantVO::from($value);
        $this->assertEquals(new TenantRef('one'), $ref->value());
        $other = TrustedClientTenantVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = TrustedClientTenantVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = TrustedClientTenantVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(TrustedClientTenantVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = TrustedClientTenantVO::from(new TenantRef('one'));
        $same = TrustedClientTenantVO::from(new TenantRef('one'));
        $other = TrustedClientTenantVO::from(new TenantRef('other'));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_empty(): void
    {
        $ref = TrustedClientTenantVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = TrustedClientTenantVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
}
